{
  "missing_information": [
    {
      "category": "input",
      "gap": "No information on how stock levels are currently tracked or monitored",
      "why_it_matters": "Without knowing how low inventory is detected (visual check, list, app, etc.), it is impossible to determine whether monitoring can be automated or triggered digitally"
    },
    {
      "category": "decision",
      "gap": "No criteria defined for what 'getting low' means for each supply item",
      "why_it_matters": "Reorder thresholds are essential for automating replenishment triggers; without defined thresholds, the system cannot decide when to act"
    },
    {
      "category": "system",
      "gap": "No information on where or how orders are placed (retailer website, app, subscription service, physical store)",
      "why_it_matters": "The ordering channel determines whether the purchasing step can be automated or integrated with an external platform"
    },
    {
      "category": "actor",
      "gap": "It is unclear whether one person always performs all steps or if multiple caregivers share responsibility",
      "why_it_matters": "If multiple actors are involved, coordination and handoff points must be modeled and may introduce synchronization challenges for automation"
    },
    {
      "category": "frequency",
      "gap": "No indication of how often stock checks are performed or how frequently orders are placed",
      "why_it_matters": "Frequency affects whether a scheduled automated check is feasible and helps estimate the volume of replenishment events"
    },
    {
      "category": "output",
      "gap": "No description of what happens after delivery items are put away (e.g., updating a record, confirming receipt)",
      "why_it_matters": "If there is no confirmation or record update step, inventory tracking remains inaccurate and automation of the full cycle cannot close the loop"
    },
    {
      "category": "exception",
      "gap": "No mention of what happens when a delivery is incomplete, incorrect, or delayed",
      "why_it_matters": "Exception handling is critical for robust automation; unhandled exceptions can leave stock critically low without triggering corrective action"
    },
    {
      "category": "data_availability",
      "gap": "No information on whether a list of required supplies and their quantities is maintained anywhere",
      "why_it_matters": "A structured supply list is a prerequisite for any automated monitoring or ordering logic"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "How do you currently keep track of which supplies are running low — for example, do you do a visual check, maintain a written or digital list, or use an app?",
      "targets": ["input", "data_availability"]
    },
    {
      "id": "Q2",
      "question": "For each type of supply, is there a specific quantity or point at which you consider it 'low enough' to reorder, and if so, how is that threshold determined?",
      "targets": ["decision"]
    },
    {
      "id": "Q3",
      "question": "Where and how do you place orders — for example, through a specific retailer's website or app, a subscription service, or a physical store?",
      "targets": ["system", "integration_constraint"]
    },
    {
      "id": "Q4",
      "question": "How often do you check supply levels, and is this done on a regular schedule or only when you happen to notice something is running out?",
      "targets": ["frequency", "manual_effort"]
    },
    {
      "id": "Q5",
      "question": "After you put a delivery away, do you update any record or list to reflect the new stock levels, or is that step not currently part of the process?",
      "targets": ["output"]
    },
    {
      "id": "Q6",
      "question": "What do you do if a delivery arrives with missing or wrong items — is there a specific step you follow to resolve it?",
      "targets": ["exception"]
    }
  ]
}
